using System;

public class HealthProbeResult
{
    public bool IsDatabaseConnected { get; set; }
    public bool IsProcessResponsive { get; set; }

    public int EvaluateLiveness()
    {
        return IsProcessResponsive ? 200 : 500;
    }

    public int EvaluateReadiness()
    {
        return (IsProcessResponsive && IsDatabaseConnected) ? 200 : 503;
    }
}

public class Program
{
    public static void Main()
    {
        var health = new HealthProbeResult
        {
            IsProcessResponsive = true,
            IsDatabaseConnected = false
        };

        int liveness = health.EvaluateLiveness();
        int readiness = health.EvaluateReadiness();

        Console.WriteLine($"Liveness Status  : {liveness} (Harus 200: JANGAN bunuh pod!)");
        Console.WriteLine($"Readiness Status : {readiness} (Harus 503: Jangan kirim trafik sementara!)");
    }
}

